func (this *Hibachi) ParseMarket(market any) map[string]any {
	var marketId *string = this.SafeString(market, "symbol")
	var numericId *float64 = this.SafeNumber(market, "id")
	var marketType string = "swap"
	var baseId *string = this.SafeString(market, "underlyingSymbol")
	var quoteId *string = this.SafeString(market, "settlementSymbol")
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	var settleId *string = this.SafeString(market, "settlementSymbol")
	var settle *string = this.SafeCurrencyCode(settleId)
	if (base == nil) || (quote == nil) || (settle == nil) {
		return nil
	}
	var symbol string = *base + "/" + *quote + ":" + *settle
	var created *int64 = this.SafeIntegerProduct(market, "marketCreationTimestamp", 1000)
	return this.SafeMarketStructure(map[string]any{
		"id":             marketId,
		"numericId":      numericId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           marketType,
		"spot":           false,
		"margin":         false,
		"swap":           true,
		"future":         false,
		"option":         false,
		"active":         (this.SafeString(market, "status") != nil && *this.SafeString(market, "status") == "LIVE"),
		"contract":       true,
		"linear":         true,
		"inverse":        false,
		"contractSize":   this.ParseNumber("1"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "underlyingDecimals"))),
			"price":  this.ParseNumber(Precise.StringDiv(this.SafeString(this.SafeList(market, "orderbookGranularities", []any{}), 0), "10000")),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "minNotional"),
				"max": nil,
			},
		},
		"created": created,
		"info":    market,
	})
}

