	//         "1",
	//         "10"
	//     ],
	//     "riskFactorForOrders": "0.066667",
	//     "riskFactorForPositions": "0.030000",
	//     "settlementDecimals": 6,
	//     "settlementSymbol": "USDT",
	//     "status": "LIVE",
	//     "stepSize": "0.000000001",
	//     "symbol": "ETH/USDT-P",
	//     "tickSize": "0.000001",
	//     "underlyingDecimals": 9,
	//     "underlyingSymbol": "ETH"
