func (this *Hibachi) EncodeWithdrawMessage(amount any, maxFees *float64, address string) any {
	// Converting them to internal representation:
	// - Quantity: Internal = External * (10^6)
	// - maxFees: Internal = External * (10^6)
	// We only have USDT as our currency as this time
	var USDTAssetId int = 1
	var USDTFactor string = "1000000"
	var amountStr *string = this.NumberToString(amount)
	var maxFeesStr *string = this.NumberToString(maxFees)
	var one string = "1"
	var quantityInternal *string = Precise.StringDiv(Precise.StringMul(amountStr, USDTFactor), one, 0)
	var maxFeesInternal *string = Precise.StringDiv(Precise.StringMul(maxFeesStr, USDTFactor), one, 0)
	// Encoding
	var usdtAsset16 string = this.IntToBase16(USDTAssetId)
	var usdtAssetPadded string = (strings.Repeat("0", max(8-len(usdtAsset16), 0)) + usdtAsset16)[max(len(usdtAsset16)-8, 0):]
	var encodedAssetId []byte = this.Base16ToBinary(usdtAssetPadded)
	var quantity16 string = this.IntToBase16(this.ParseToInt(quantityInternal))
	var quantityPadded string = (strings.Repeat("0", max(16-len(quantity16), 0)) + quantity16)[max(len(quantity16)-16, 0):]
	var encodedQuantity []byte = this.Base16ToBinary(quantityPadded)
	var maxFees16 string = this.IntToBase16(this.ParseToInt(maxFeesInternal))
	var maxFeesPadded string = (strings.Repeat("0", max(16-len(maxFees16), 0)) + maxFees16)[max(len(maxFees16)-16, 0):]
	var encodedMaxFees []byte = this.Base16ToBinary(maxFeesPadded)
	var encodedAddress []byte = this.Base16ToBinary(address)
	var message []byte = this.BinaryConcat(encodedAssetId, encodedQuantity, encodedMaxFees, encodedAddress)
	return message
}

/**
 * @method
 * @name hibachi#withdraw
 * @description make a withdrawal
 * @see https://api-doc.hibachi.xyz/#6421625d-3e45-45fa-be9b-d2a0e780c090
 * @param {string} code unified currency code, only support USDT
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Hibachi) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Hibachi) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var withdrawAddress string = Slice(address, int64(-40), nil)
	// Get the withdraw fees

	r := <-this.PublicGetMarketExchangeInfo(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var exchangeInfo map[string]any = r.Value
	// {
	//      "feeConfig": {
	//          "depositFees": "0.004518",
	//          "tradeMakerFeeRate": "0.00000000",
	//          "tradeTakerFeeRate": "0.00020000",
	//          "transferFeeRate": "0.00010000",
	//          "withdrawalFees": "0.012050"
	//    },
	// }
	var feeConfig map[string]any = SafeMapTyped(exchangeInfo, "feeConfig")
	var maxFees *float64 = this.SafeNumber(feeConfig, "withdrawalFees")
	// Generate the signature
	var message any = this.EncodeWithdrawMessage(amount, maxFees, withdrawAddress)
	var signature string = this.SignMessage(message, this.PrivateKey)
	var request map[string]any = map[string]any{
		"accountId":       this.GetAccountId(),
		"coin":            "USDT",
		"network":         "ARBITRUM",
		"withdrawAddress": withdrawAddress,
		"selfWithdrawal":  false,
		"quantity":        this.NumberToString(amount),
		"maxFees":         this.NumberToString(maxFees),
		"signature":       signature,
	}

	r1 := <-this.PrivatePostCapitalWithdraw(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}

	// At this time the response body is empty. A 200 response means the withdraw request is accepted and sent to process
	//
	// {}
	//
	ch <- AsyncResult[Transaction]{Value: TransactionFromMap(map[string]any{
		"info":        nil,
		"id":          nil,
		"txid":        nil,
		"timestamp":   this.Milliseconds(),
		"datetime":    nil,
		"address":     nil,
		"addressFrom": nil,
		"addressTo":   withdrawAddress,
		"tag":         nil,
		"tagFrom":     nil,
		"tagTo":       nil,
		"type":        "withdrawal",
		"amount":      amount,
		"currency":    code,
		"status":      "pending",
		"fee": map[string]any{
			"currency": "USDT",
			"cost":     maxFees,
		},
		"network":  "ARBITRUM",
		"updated":  nil,
		"comment":  nil,
		"internal": nil,
	})}
	return nil
}
func (this *Hibachi) Nonce() int64 {
	return this.Milliseconds()
}
func (this *Hibachi) SignMessage(message any, privateKey any) string {
	if GetLength(privateKey) == 44 {
		// For Exchange Managed account, the key length is 44 and we use HMAC to sign the message
		return this.Hmac(message, this.Encode(privateKey), sha256, "hex")
	} else {
		// For Trustless account, the key length is 66 including '0x' and we use ECDSA to sign the message
		var hash any = this.Hash(message, sha256, "hex")
		var signature map[string]any = Ecdsa(Slice(hash, int64(-64), nil), Slice(privateKey, int64(-64), nil), secp256k1, nil)
		var r *string = this.SafeString(signature, "r", "")
		var s *string = this.SafeString(signature, "s", "")
		var v string = this.IntToBase16(signature["v"])
		return (strings.Repeat("0", max(64-len(*r), 0)) + *r)[max(len(*r)-64, 0):] + (strings.Repeat("0", max(64-len(*s), 0)) + *s)[max(len(*s)-64, 0):] + (strings.Repeat("0", max(2-len(v), 0)) + v)[max(len(v)-2, 0):]
	}
}

