func (this *Hibachi) ParseSettlement(settlement any, optionalArgs ...any) map[string]any {
	//
	//     {
	//         "direction": "Long",
	//         "indexPrice": "81.8781761",
	//         "quantity": "0.10000000",
	//         "settledAmount": "0.00005994405060281047",
	//         "symbol": "SOL/USDT-P",
	//         "timestamp": 1783389600,
	//         "timestampNsPartial": 0
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeTimestamp(settlement, "timestamp")
	var marketId *string = this.SafeString(settlement, "symbol")
	return map[string]any{
		"info":      settlement,
		"symbol":    this.SafeSymbol(marketId, market),
		"price":     this.SafeNumber(settlement, "indexPrice"),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
}
func (this *Hibachi) ParseSettlements(settlements []any, optionalArgs ...any) []any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var result []any = []any{}
	for i := 0; i < len(settlements); i++ {
		result = append(result, this.ParseSettlement(DerefScalar(settlements[i]), market))
	}
	return result
}

/**
 * @method
 * @name hibachi#fetchMySettlementHistory
 * @description fetches historical settlement records of the user
 * @see https://api-doc.hibachi.xyz/#28185336-04b7-4480-bcc8-a33516ad458b
 * @param {string} [symbol] unified market symbol of the settlement history
 * @param {int} [since] timestamp in ms of the earliest settlement
 * @param {int} [limit] the maximum number of settlements to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest settlement
 * @returns {object[]} a list of [settlement history objects]{@link https://docs.ccxt.com/#/?id=settlement-history-structure}
 */
func (this *Hibachi) FetchMySettlementHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]map[string]any] {
	ch := make(chan AsyncResult[[]map[string]any], 1)
	go this.fetchMySettlementHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Hibachi) fetchMySettlementHistoryBody(ch chan AsyncResult[[]map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var market map[string]any = nil
	var request map[string]any = map[string]any{
		"accountId": this.GetAccountId(),
	}
	var symbolResolved any = nil
	if symbol != nil {
		market = this.Market(symbol)
		request["contractId"] = market["numericId"]
		if derefPtr := this.SafeString(market, "symbol"); derefPtr != nil {
			symbolResolved = *derefPtr
		} else {
			symbolResolved = nil
		}
	}
	if since != nil {
		request["startTime"] = this.ParseToInt(float64(*since) / 1000)
	}
	if limit != nil {
		request["limit"] = limit
	}
	var untilparamsUntilVariable []any = this.HandleOptionIntegerAndParamsNullable(params, "fetchMySettlementHistory", "until")
	until := untilparamsUntilVariable[0]
	paramsUntil := untilparamsUntilVariable[1]
	if !IsEqual(until, nil) {
		request["endTime"] = this.ParseToInt(float64(*until.(*int64)) / 1000)
	}

	r1 := <-this.PrivateGetTradeAccountSettlementsHistory(this.Extend(request, paramsUntil))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "settlements": [
	//             {
	//                 "direction": "Long",
	//                 "indexPrice": "81.8781761",
	//                 "quantity": "0.10000000",
	//                 "settledAmount": "0.00005994405060281047",
	//                 "symbol": "SOL/USDT-P",
	//                 "timestamp": 1783389600,
	//                 "timestampNsPartial": 0
	//             }
	//         ]
	//     }
	//
	var data []any = SafeListTypedDefault(response, "settlements", []any{})
	var settlements []any = this.ParseSettlements(data, market)
	var sorted []any = this.SortBy(settlements, "timestamp")

	ch <- AsyncResult[[]map[string]any]{Value: MapSliceFromList(this.FilterBySymbolSinceLimit(sorted, symbolResolved, since, limit))}
	return nil
}

