/**
 * @method
 * @name hibachi#fetchOpenInterest
 * @description retrieves the open interest of a contract trading pair
 * @see https://api-doc.hibachi.xyz/#bc34e8ae-e094-4802-8d56-3efe3a7bad49
 * @param {string} symbol unified CCXT market symbol
 * @param {object} [params] exchange specific parameters
 * @returns {object} an open interest structure{@link https://docs.ccxt.com/?id=open-interest-structure}
 */
func (this *Hibachi) FetchOpenInterestAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[OpenInterest] {
	ch := make(chan AsyncResult[OpenInterest], 1)
	go this.fetchOpenInterestBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Hibachi) fetchOpenInterestBody(ch chan AsyncResult[OpenInterest], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}

	r1 := <-this.PublicGetMarketDataOpenInterest(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//   { "totalQuantity" : "2.3299770166" }
	//
	var timestamp int64 = this.Milliseconds()

	ch <- AsyncResult[OpenInterest]{Value: this.SafeOpenInterest(map[string]any{
		"symbol":             symbol,
		"openInterestAmount": this.SafeString(response, "totalQuantity"),
		"openInterestValue":  nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"info":               response,
	}, market)}
	return nil
}

/**
 * @method
 * @name hibachi#fetchFundingRate
 * @description fetch the current funding rate
 * @see https://api-doc.hibachi.xyz/#bca696ca-b9b2-4072-8864-5d6b8c09807e
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [funding rate structure]{@link https://docs.ccxt.com/?id=funding-rate-structure}
 */
func (this *Hibachi) FetchFundingRateAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[FundingRate] {
	ch := make(chan AsyncResult[FundingRate], 1)
	go this.fetchFundingRateBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Hibachi) fetchFundingRateBody(ch chan AsyncResult[FundingRate], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}

	r1 := <-this.PublicGetMarketDataPrices(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	// {
	//     "askPrice": "3514.650296",
	//     "bidPrice": "3513.596112",
	//     "fundingRateEstimation": {
	//         "estimatedFundingRate": "0.000001",
	//         "nextFundingTimestamp": 1712707200
	//     },
	//     "markPrice": "3514.288858",
	//     "spotPrice": "3514.715000",
	//     "symbol": "ETH/USDT-P",
	//     "tradePrice": "2372.746570"
	// }
	//
	var funding map[string]any = this.SafeDictMap(response, "fundingRateEstimation", map[string]any{})
	var timestamp int64 = this.Milliseconds()
	var nextFundingTimestamp *int64 = this.SafeIntegerProduct(funding, "nextFundingTimestamp", 1000)

	ch <- AsyncResult[FundingRate]{Value: FundingRateFromMap(map[string]any{
		"info":                     funding,
		"symbol":                   market["symbol"],
		"markPrice":                nil,
		"indexPrice":               nil,
		"interestRate":             this.ParseNumber("0"),
		"estimatedSettlePrice":     nil,
		"timestamp":                timestamp,
		"datetime":                 this.Iso8601(timestamp),
		"fundingRate":              this.SafeNumber(funding, "estimatedFundingRate"),
		"fundingTimestamp":         nextFundingTimestamp,
		"fundingDatetime":          this.Iso8601(nextFundingTimestamp),
		"nextFundingRate":          nil,
		"nextFundingTimestamp":     nil,
		"nextFundingDatetime":      nil,
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
		"interval":                 "8h",
	})}
	return nil
}

/**
 * @method
 * @name hibachi#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://api-doc.hibachi.xyz/#079586af-0d94-41ea-99bb-7afcd93bf438
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
 * @param {int} [limit] the maximum amount of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
 */
func (this *Hibachi) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingRateHistory] {
	ch := make(chan AsyncResult[[]FundingRateHistory], 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Hibachi) fetchFundingRateHistoryBody(ch chan AsyncResult[[]FundingRateHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}

	r1 := <-this.PublicGetMarketDataFundingRates(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	// {
	//     "data": [
	//         {
	//             "contractId": 2,
	//             "fundingTimestamp": 1753488000,
	//             "fundingRate": "0.000137",
	//             "indexPrice": "117623.65010"
	//         }
	//     ]
	// }
	//
	var data []any = SafeListTyped(response, "data")
	var rates []any = []any{}
	for i := 0; i < len(data); i++ {
		var entry any = data[i]
		var timestamp *int64 = this.SafeIntegerProduct(entry, "fundingTimestamp", 1000)
		rates = append(rates, map[string]any{
			"info":        entry,
			"symbol":      symbol,
			"fundingRate": this.SafeNumber(entry, "fundingRate"),
			"timestamp":   timestamp,
			"datetime":    this.Iso8601(timestamp),
		})
	}
	var sorted []any = this.SortBy(rates, "timestamp")

	ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(this.FilterBySymbolSinceLimit(sorted, symbol, since, limit))}
	return nil
}

func NewHibachi(userConfig map[string]any) *Hibachi {
	p := newHibachi()
	p.Init(userConfig)
	return p
}

func (this *Hibachi) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

